<script type="application/ld+json">
{"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Что такое целевая субсидия юридическому лицу?", "acceptedAnswer": {"@type": "Answer", "text": "Это бюджетные средства, предоставляемые организации на безвозмездной и безвозвратной основе для конкретной цели — возмещения затрат или финансового обеспечения производства товаров, работ и услуг. Регулируются статьёй 78 Бюджетного кодекса."}}, {"@type": "Question", "name": "Какие бывают виды субсидий?", "acceptedAnswer": {"@type": "Answer", "text": "По назначению — на возмещение затрат (недополученных доходов) и на финансовое обеспечение затрат. Первые приходят по факту понесённых расходов, вторые выделяются авансом под будущие затраты. Отдельно выделяют гранты в форме субсидий."}}, {"@type": "Question", "name": "Чем регулируются субсидии юрлицам?", "acceptedAnswer": {"@type": "Answer", "text": "Статьёй 78 БК РФ — для коммерческих производителей, статьёй 78.1 — для некоммерческих организаций и грантов, статьёй 78.2 — для субсидий на капитальные вложения. Механизм казначейского сопровождения задан главой 24.4 БК РФ."}}, {"@type": "Question", "name": "Нужно ли возвращать субсидию?", "acceptedAnswer": {"@type": "Answer", "text": "Если получатель выполнил условия и потратил деньги по целевому назначению — нет. Но средства, использованные не по назначению или с нарушением условий соглашения, подлежат возврату в бюджет."}}, {"@type": "Question", "name": "Когда субсидия попадает под казначейское сопровождение?", "acceptedAnswer": {"@type": "Answer", "text": "Случаи определяются ежегодно законом о федеральном бюджете, а общий механизм — главой 24.4 БК РФ. Чаще под сопровождение попадают субсидии на финансовое обеспечение затрат, выделяемые авансом."}}, {"@type": "Question", "name": "Подлежит ли субсидия ИП казначейскому сопровождению?", "acceptedAnswer": {"@type": "Answer", "text": "Как правило, нет. Для индивидуальных предпринимателей и крестьянских (фермерских) хозяйств казначейское сопровождение субсидий обычно не требуется. Точный режим зависит от условий предоставления."}}, {"@type": "Question", "name": "Как подтвердить целевое использование субсидии?", "acceptedAnswer": {"@type": "Answer", "text": "Под сопровождением — через санкционирование каждого платежа и итоговую отчётность. Расход подтверждается документами-основаниями (договор, акт, накладная), а отчёт формируется на основе проведённых операций."}}, {"@type": "Question", "name": "Чем субсидия отличается от бюджетной инвестиции?", "acceptedAnswer": {"@type": "Answer", "text": "Субсидия безвозмездна и не даёт государству долю в бизнесе. Бюджетная инвестиция, наоборот, влечёт возникновение государственной доли в имуществе. Для большинства организаций речь идёт о субсидии по статье 78."}}, {"@type": "Question", "name": "На какой счёт зачисляется сопровождаемая субсидия?", "acceptedAnswer": {"@type": "Answer", "text": "На лицевой счёт получателя в территориальном органе казначейства, а не на обычный банковский счёт. С этого счёта каждый платёж проходит санкционирование."}}]}
</script>
