{"@context": "https://schema.org", "@type": "HowTo", "name": "Как организовать работу с целевой субсидией под сопровождением", "inLanguage": "ru-RU", "step": [{"@type": "HowToStep", "position": 1, "name": "Изучить соглашение", "text": "Зафиксировать цель, направления расходов, сроки и требования к отчётности."}, {"@type": "HowToStep", "position": 2, "name": "Открыть лицевой счёт", "text": "Открыть лицевой счёт в территориальном органе казначейства для зачисления субсидии."}, {"@type": "HowToStep", "position": 3, "name": "Настроить раздельный учёт", "text": "Обособить средства субсидии в учёте от собственной выручки и других источников."}, {"@type": "HowToStep", "position": 4, "name": "Подготовить документы-основания", "text": "Привести договоры и первичные документы в соответствие с целями субсидии."}, {"@type": "HowToStep", "position": 5, "name": "Проводить расходы под санкционированием", "text": "Оформлять платежи с верным назначением и пакетом подтверждающих документов."}, {"@type": "HowToStep", "position": 6, "name": "Отчитываться о целевом использовании", "text": "Формировать отчётность и подтверждать, что деньги пошли по назначению."}]}
